    _wB._scrape_via_ig_public = lambda h: {"error": "Instagram rate-limit (429)."}
    _c1 = _wB._compute_insta_3_stats("cliquet", force=True)
    _c2 = _wB._compute_insta_3_stats("cliquet", force=True)
