    _srcCa = _plCa.Path("web_upload.py").read_text(encoding="utf-8")
    _iJs = _srcCa.find("function capRenderCards(){")
    _jsCard = _srcCa[_iJs:_srcCa.find("function capSave(", _iJs)] if _iJs > 0 else ""
