try:
    import jb_objectifs as _obT
    _dosOb = pathlib.Path(tempfile.mkdtemp(prefix="objectifs_"))
    _svOb = (_obT.OBJECTIFS_FILE, _obT.HISTO_FILE)
    _obT.OBJECTIFS_FILE = _dosOb / "obj.json"
    _obT.HISTO_FILE = _dosOb / "histo.json"
    try:
        _nowOb = time.time()
        _jourOb = _obT.aujourdhui()

        def _cptOb(nom, cree_j=None, dernier_h=None, banni=False, poste=False):
            """Rend (compte, entree de cache) pour un cas de figure."""
            a = {"username": nom}
            if cree_j is not None:
                a["created_at"] = int(_nowOb - cree_j * 86400)
            s = {}
            if banni:
                s["banned"] = True
            if dernier_h is not None:
                s["last_reel_at"] = _dtVtk.datetime.fromtimestamp(
                    _nowOb - dernier_h * 3600, _dtVtk.timezone.utc).isoformat()
            if poste:
                s["reel_days"] = {_jourOb: 1}
            return a, {nom: s}

        _cOb, _sOb = [], {}
        for _a, _s in (
                _cptOb("publie_auj", cree_j=40, dernier_h=2, poste=True),
                _cptOb("publie_hier", cree_j=40, dernier_h=20),
                _cptOb("silencieux", cree_j=40, dernier_h=100),
                _cptOb("tout_neuf", cree_j=1),
                _cptOb("cree_ce_jour", cree_j=0),
                _cptOb("banni", cree_j=40, dernier_h=500, banni=True)):
            _cOb.append(_a)
            _sOb.update(_s)
        _eOb = _obT.etat_fiche("jessye", "VA NOUM 1X1", _cOb, _sOb, _nowOb)

        check("objectif : les comptes sont tous comptés", _eOb["total"] == 6, _eOb["total"])
        # Le coeur de la definition voulue : publie sous 48 h OU warm-up.
        check("objectif : actif = a publié sous 48 h ou vient d être créé",
              _eOb["actifs"] == 4, f"{_eOb['actifs']} au lieu de 4")
        check("objectif : un banni n est jamais actif", _eOb["bannis"] == 1)
        # Un compte en warm-up n a rien oublie : il n a pas encore commence.
        check("objectif : le warm-up n est pas un oubli",
              _eOb["oublies"] == 1, f"{_eOb['oublies']} oubli(s), attendu 1")
        check("objectif : « a publié aujourd hui » se compte à part",
              _eOb["publie"] == 1, _eOb["publie"])
        check("objectif : « ajoutés aujourd hui » aussi",
              _eOb["ajoutes"] == 1, _eOb["ajoutes"])
        check("objectif : le défaut est 20", _eOb["objectif"] == 20, _eOb["objectif"])

        # Le seuil s arrondit au SUPERIEUR : accepter 15 sur un objectif de 19
        # reviendrait a valider 78,9 %, c est-a-dire moins que les 80 % annonces.
        check("objectif : seuil 80 % arrondi au supérieur",
              (_obT._seuil(30), _obT._seuil(19), _obT._seuil(10)) == (24, 16, 8),
              str((_obT._seuil(30), _obT._seuil(19), _obT._seuil(10))))
        check("objectif : un objectif nul ne fabrique pas un seuil",
              _obT._seuil(0) == 0)

        check("objectif : on peut le fixer",
              _obT.fixer_objectif("jessye", "VA NOUM 1X1", 12) == 12)
        check("objectif : et il est relu",
              _obT.objectif_de("jessye", "VA NOUM 1X1") == 12)
        # Zero serait TOUJOURS atteint : la pastille deviendrait muette sans
        # que personne le remarque. On revient au defaut.
        check("objectif : zéro remet au défaut, il ne pose pas zéro",
              _obT.fixer_objectif("jessye", "VA NOUM 1X1", 0) == 20
              and _obT.objectif_de("jessye", "VA NOUM 1X1") == 20)
        check("objectif : une saisie absurde est bornée",
              _obT.fixer_objectif("jessye", "VA NOUM 1X1", 99999) == 999)
        check("objectif : du texte ne casse rien",
              _obT.fixer_objectif("jessye", "VA NOUM 1X1", "beaucoup") == 20)
        # La casse du nom ne doit pas fabriquer une deuxieme fiche : il se
        # ressaisit a la main, a la commande Discord comme au dashboard.
        _obT.fixer_objectif("jessye", "VA NOUM 1X1", 17)
        check("objectif : la casse du nom ne crée pas une seconde fiche",
              _obT.objectif_de("JESSYE", "va noum 1x1") == 17)
        _obT.fixer_objectif("jessye", "VA NOUM 1X1", 0)

        # Quinzaines : memes bornes que la paie et le report de clics.
        check("quinzaine : du 1 au 15",
              _obT.quinzaine("2026-08-07") == ("2026-08-01", "2026-08-15"))
        check("quinzaine : du 16 à la fin du mois",
              _obT.quinzaine("2026-08-30") == ("2026-08-16", "2026-08-31"))
        check("quinzaine : février tombe juste",
              _obT.quinzaine("2026-02-20") == ("2026-02-16", "2026-02-28"))
        check("quinzaine : décembre ne déborde pas sur l année suivante",
              _obT.quinzaine("2026-12-20") == ("2026-12-16", "2026-12-31"))

        # Historique et bilan.
        for _j, _atteint in (("2026-08-16", True), ("2026-08-17", True),
                             ("2026-08-18", False), ("2026-08-19", True)):
            _obT.enregistrer_jour([{"identite": "jessye", "va": "VA NOUM 1X1",
                                    "total": 30, "actifs": 25 if _atteint else 10,
                                    "publie": 5, "ajoutes": 0, "oublies": 2,
                                    "bannis": 1, "objectif": 30,
                                    "atteint": _atteint}], _j)
        _bOb = _obT.bilan_quinzaine("jessye", "VA NOUM 1X1", "2026-08-19")
        check("bilan : les journées notées sont comptées",
              _bOb["jours_notes"] == 4, _bOb)
        check("bilan : et les journées tenues aussi", _bOb["jours_tenus"] == 3, _bOb)
        # 3 tenues sur 4 font 75 % : SOUS la barre des 80 %, donc orange. La
        # pastille reprend le seuil de la journee, elle n a pas le sien.
        check("bilan : la pastille suit la proportion, au même seuil que le jour",
              _bOb["pastille"] == "🟠", _bOb)
        # LE point : un bot a l arret a minuit ne doit pas se lire comme une
        # journee ratee, sinon la premiere coupure punit un bon VA.
        check("bilan : une journée sans report ne compte NI en bien ni en mal",
              _bOb["jours_notes"] == 4 and _bOb["pct"] == 75.0, _bOb)
        check("bilan : réécrire la même journée ne la compte pas deux fois",
              (_obT.enregistrer_jour([{"identite": "jessye", "va": "VA NOUM 1X1",
                                       "atteint": True, "objectif": 30}], "2026-08-19")
               is not None)
              and _obT.bilan_quinzaine("jessye", "VA NOUM 1X1",
                                       "2026-08-19")["jours_notes"] == 4)
        check("bilan : la quinzaine d à côté n est pas mélangée",
              _obT.bilan_quinzaine("jessye", "VA NOUM 1X1", "2026-08-05")["jours_notes"] == 0)
        # Une pastille rouge apres une seule journee condamnerait sur un
        # echantillon de un.
        check("bilan : pastille muette tant qu on a moins de 3 journées",
              _obT.pastille(0, 1) == "⚪" and _obT.pastille(0, 2) == "⚪")
        check("bilan : puis elle parle",
              (_obT.pastille(3, 3), _obT.pastille(2, 3), _obT.pastille(1, 3))
              == ("🟢", "🟠", "🔴"))

        # Le rendu Discord : il doit tenir sans planter et dire l essentiel.
        import cogs.reportcomptes as _rcT

        def _joinOb(msgs):
            """bloc_quinzaine rend une LISTE : un mois de carres pour vingt
            fiches ne tient pas dans un seul message Discord. Les essais la
            recollent pour chercher dedans."""
            return "\n".join(msgs) if isinstance(msgs, list) else msgs

        # UNE ligne par fiche, et rien de plus. La premiere version en faisait
        # cinq, avec pourcentages et barre : sur vingt-quatre VAs c'etait un mur
        # que personne ne lit. « Je veux pas un truc si complet », mot pour mot.
        _txtOb = _rcT.ligne_fiche(_eOb)
        check("report : la ligne tient sur UNE ligne",
              "\n" not in _txtOb, repr(_txtOb[:120]))
        check("report : elle nomme la fiche", "VA NOUM 1X1" in _txtOb, _txtOb)
        check("report : elle donne les comptes qui tournent sur l objectif",
              "4/20" in _txtOb, _txtOb)
        check("report : elle donne le nombre total de comptes",
              "6 comptes" in _txtOb, _txtOb)
        check("report : elle dit les oublis", "1 oubli" in _txtOb, _txtOb)
        # Zero oubli se DIT, il ne se devine pas par l absence de mention.
        check("report : pas d oubli se dit aussi",
              "pas d'oubli" in _rcT.ligne_fiche(dict(_eOb, oublies=0)),
              _rcT.ligne_fiche(dict(_eOb, oublies=0)))
        check("report : objectif non tenu -> pastille rouge", "🔴" in _txtOb, _txtOb)
        check("report : objectif tenu -> pastille verte",
              "✅" in _rcT.ligne_fiche(dict(_eOb, atteint=True)))

        # Le message du jour : UN seul, toutes les fiches dedans, du pire au
        # meilleur — vingt-quatre notifications d'affilee chaque nuit, c'etait
        # le salon noye.
        _msgsOb = _rcT.bloc_jour(
            [dict(_eOb, va="FICHE A", actifs=28, atteint=True),
             dict(_eOb, va="FICHE B", actifs=2, atteint=False)],
            "2026-08-30", "jessye")
        check("report : un seul message pour toutes les fiches",
              len(_msgsOb) == 1, len(_msgsOb))
        check("report : les deux fiches y sont",
              "FICHE A" in _msgsOb[0] and "FICHE B" in _msgsOb[0])
        # L ORDRE EST CELUI DU SITE, pas un classement. On triait du pire au
        # meilleur ; c est plus efficace pour reperer qui decroche, mais on
        # perdait la correspondance ligne a ligne avec l ecran qu on a sous les
        # yeux — et on passe de l un a l autre en permanence.
        check("report : l ordre reçu est conservé, pas re-trié",
              _msgsOb[0].index("FICHE A") < _msgsOb[0].index("FICHE B"),
              _msgsOb[0][:400])
        # Sans legende, « 2/30 » ne dit pas de quoi on parle.
        check("report : la légende explique le x/30, une seule fois",
              _msgsOb[0].count("comptes qui tournent") == 1, _msgsOb[0][:200])
        check("report : l en-tête nomme l identité suivie",
              "@jessye" in _msgsOb[0], _msgsOb[0][:120])
        # Discord refuse au-dela de 2000 caracteres : soixante fiches doivent
        # etre coupees en plusieurs messages, chacun avec sa legende.
        _longsOb = _rcT.bloc_jour(
            [dict(_eOb, va=f"FICHE {_i:02d}") for _i in range(60)], "2026-08-30")
        check("report : une longue liste est découpée",
              len(_longsOb) > 1, len(_longsOb))
        # DISCORD COMPTE EN UTF-16 : un carre colore vaut DEUX unites, pas une.
        # Mesurer en caracteres Python laissait passer des messages de 2340
        # unites — refuses a l envoi, l erreur perdue dans un journal, et seul
        # le dernier petit morceau arrivait. On lisait quatre fiches sur vingt.
        check("report : chaque morceau tient sous la limite Discord",
              all(_rcT._taille(m) <= 2000 for m in _longsOb),
              [_rcT._taille(m) for m in _longsOb])
        check("mesure : un carré coloré compte pour deux",
              _rcT._taille("🟥") == 2 and _rcT._taille("a") == 1,
              (_rcT._taille("🟥"), _rcT._taille("a")))
        check("report : chaque morceau garde sa légende",
              all("comptes qui tournent" in m for m in _longsOb))
        check("report : aucune fiche perdue au découpage",
              sum(m.count("FICHE ") for m in _longsOb) == 60,
              sum(m.count("FICHE ") for m in _longsOb))
        _pinOb = _joinOb(_rcT.bloc_quinzaine(
            [{"e": _eOb, "bilan": _bOb}], "2026-08-16", "2026-08-31"))
        # LE BILAN SERT A PAYER : il lui faut le « @ » Discord (le nom de la
        # fiche designe un telephone, pas quelqu un a qui virer de l argent) et
        # le detail JOUR PAR JOUR — « 12/14 » ne dit pas s il a lache trois
        # jours d affilee ou un jour de temps en temps.
        _bJ = _obT.bilan_quinzaine("jessye", "VA NOUM 1X1", "2026-08-19")
        check("bilan : la suite jour par jour est rendue",
              _bJ.get("suite") == ["tenu", "tenu", "rate", "tenu"], _bJ.get("suite"))
        # Les jours a VENIR ne sont pas des jours rates : on s arrete a la date
        # demandee, sinon on reproche a quelqu un de ne pas avoir encore vecu.
        check("bilan : la suite s arrête au jour demandé",
              len(_obT.bilan_quinzaine("jessye", "VA NOUM 1X1", "2026-08-17")["suite"]) == 2)
        # Une nuit sans report n est NI verte NI rouge.
        _bTrou = _obT.bilan_quinzaine("jessye", "VA NOUM 1X1", "2026-08-21")
        check("bilan : une nuit sans report reste blanche",
              _bTrou["suite"][-1] == "inconnu" and _bTrou["suite"][-2] == "inconnu",
              _bTrou["suite"])
        # Les carres blancs de TETE disparaissent : la quinzaine a commence
        # avant qu on se mette a mesurer, et quatorze blancs en tete se
        # lisaient comme quatorze echecs. Les trous du MILIEU restent, eux :
        # une nuit ou le bot n a pas tourne est une information.
        _obT.enregistrer_jour([{"identite": "z", "va": "Z", "objectif": 30,
                                "atteint": True}], "2026-08-29")
        _obT.enregistrer_jour([{"identite": "z", "va": "Z", "objectif": 30,
                                "atteint": False}], "2026-08-30")
        _bTete = _obT.bilan_quinzaine("z", "Z", "2026-08-30")
        # La bande couvre TOUTE la quinzaine ecoulee : du 16 au 30, quinze
        # jours, dont les treize d avant la premiere mesure.
        check("bilan : la bande couvre toute la quinzaine écoulée",
              len(_bTete["suite"]) == 15, len(_bTete["suite"]))
        check("bilan : et se termine par les deux jours mesurés",
              _bTete["suite"][-2:] == ["tenu", "rate"], _bTete["suite"][-3:])
        _obT.enregistrer_jour([{"identite": "y", "va": "Y", "objectif": 30,
                                "atteint": True}], "2026-08-27")
        _obT.enregistrer_jour([{"identite": "y", "va": "Y", "objectif": 30,
                                "atteint": True}], "2026-08-30")
        check("bilan : un trou au milieu reste visible",
              _obT.bilan_quinzaine("y", "Y", "2026-08-30")["suite"][-4:]
              == ["tenu", "inconnu", "inconnu", "tenu"],
              _obT.bilan_quinzaine("y", "Y", "2026-08-30")["suite"][-4:])
        # Pas de BLANC : dans un salon sombre il saute aux yeux, et une
        # quinzaine a peine commencee avait l air d un mur d echecs.
        # Deux couleurs seulement, demande deux fois. Une nuit sans report
        # s affiche donc en rouge — mais elle ne compte PAS dans le score, et
        # la legende le dit.
        # TROIS niveaux dans la bande, aux memes seuils que la pastille de
        # quinzaine : un carre et une pastille ne doivent pas raconter deux
        # histoires differentes sur le meme ecran.
        for _a, _att in ((30, "tenu"), (24, "tenu"), (23, "moyen"),
                         (15, "moyen"), (14, "rate"), (0, "rate")):
            check(f"jour : {_a}/30 -> {_att}",
                  _obT.etat_du_jour({"actifs": _a, "objectif": 30,
                                     "atteint": _a >= 24}) == _att,
                  _obT.etat_du_jour({"actifs": _a, "objectif": 30,
                                     "atteint": _a >= 24}))
        check("jour : sans chiffres, on retombe sur atteint",
              _obT.etat_du_jour({"atteint": True}) == "tenu"
              and _obT.etat_du_jour({"atteint": False}) == "rate")
        # « actifs » ABSENT n est pas « actifs a zero » : les journees notees
        # avant que ce chiffre soit garde auraient toutes vire au rouge, y
        # compris les tenues.
        # `atteint` FAIT FOI : c est lui qui compte dans le score, la bande ne
        # doit jamais le contredire. enregistrer_jour ecrit « actifs: 0 » par
        # defaut — sans cette regle, toutes les vieilles journees tenues
        # viraient au rouge.
        check("jour : le drapeau atteint l emporte sur le ratio",
              _obT.etat_du_jour({"objectif": 30, "actifs": 0,
                                 "atteint": True}) == "tenu")
        check("jour : et la bande ne contredit jamais le score",
              all(_obT.etat_du_jour({"objectif": 30, "actifs": _a,
                                     "atteint": True}) == "tenu"
                  for _a in (0, 5, 24, 30)))
        check("bilan : trois couleurs dans la bande",
              set(_rcT._CARRES.values()) == {"🟩", "🟠", "🟥"}, _rcT._CARRES)
        # Le SCORE reste binaire : l orange nuance ce qu on VOIT, pas ce qu on
        # compte — sinon « 12/14 j » ne voudrait plus rien dire au moment de payer.
        _obT.enregistrer_jour([{"identite": "o", "va": "O", "objectif": 30,
                                "actifs": 20, "atteint": False}], "2026-08-29")
        _obT.enregistrer_jour([{"identite": "o", "va": "O", "objectif": 30,
                                "actifs": 28, "atteint": True}], "2026-08-30")
        _bO = _obT.bilan_mois("o", "O", "2026-08-30")
        check("bilan : l orange ne compte pas comme une journée tenue",
              (_bO["q2_tenus"], _bO["q2_notes"]) == (1, 2),
              (_bO["q2_tenus"], _bO["q2_notes"]))
        check("bilan : mais il se voit dans la bande",
              _bO["suite"][-2:] == ["moyen", "tenu"], _bO["suite"][-2:])
        check("bilan : le score ignore toujours les nuits sans report",
              _obT.bilan_quinzaine("y", "Y", "2026-08-30")["jours_notes"] == 2,
              _obT.bilan_quinzaine("y", "Y", "2026-08-30"))
        check("bilan : la légende prévient que le rouge peut être une absence",
              "pas de report" in _pinOb, _pinOb[:260])

        # LE BOUTON RAFRAICHIR. Un bouton ne consomme aucune commande slash :
        # c est le seul declenchement possible depuis Discord sur ce bot, qui
        # est au plafond des cent.
        _vueOb = _rcT.BilanRefreshView()
        check("bouton : la vue porte un identifiant fixe",
              [c.custom_id for c in _vueOb.children] == ["reportcomptes:refresh"],
              [c.custom_id for c in _vueOb.children])
        # timeout=None + custom_id fixe = la vue survit a un redemarrage, a
        # condition d etre reenregistree — sinon le message epingle devient un
        # decor mort et on ne s en apercoit qu en cliquant.
        check("bouton : la vue est persistante", _vueOb.timeout is None, _vueOb.timeout)
        check("bouton : le cog la réenregistre au démarrage",
              hasattr(_rcT.ReportComptes, "cog_load"))
        check("bouton : un délai empêche de le marteler",
              _rcT._ATTENTE_S >= 30, _rcT._ATTENTE_S)
        # Seize carres a la file ne disent pas lequel est quel jour : sans les
        # dates on voit qu il a rate deux jours, pas LESQUELS.
        # PAS de dates autour de la bande : sur un panneau Discord etroit elles
        # cassaient la ligne en trois (date seule, carres, date seule). L
        # en-tete du message donne deja la periode, et la bande part toujours
        # du 1er.
        _bandeOb = _rcT.suite_jours(["tenu", "rate", "tenu"], "2026-08-16")
        check("bilan : la bande n est QUE des carrés, sans date collée",
              _bandeOb == "🟩🟥🟩", _bandeOb)
        check("bilan : sans date de début, la bande reste lisible",
              _rcT.suite_jours(["tenu"]) == "🟩", _rcT.suite_jours(["tenu"]))

        # LE MOIS ENTIER, coupé en ses deux quinzaines de paie. Le bilan ne
        # portait que sur la quinzaine en cours ; au moment de payer on veut
        # voir le mois, et les deux moities restent distinctes.
        for _d in range(1, 21):
            _obT.enregistrer_jour([{"identite": "m", "va": "M", "objectif": 30,
                                    "atteint": _d not in (7, 19)}],
                                  f"2026-08-{_d:02d}")
        _bM = _obT.bilan_mois("m", "M", "2026-08-20")
        check("mois : la bande couvre le mois jusqu à aujourd hui",
              len(_bM["suite"]) == 20, len(_bM["suite"]))
        check("mois : la première quinzaine est comptée à part",
              (_bM["q1_tenus"], _bM["q1_notes"]) == (14, 15),
              (_bM["q1_tenus"], _bM["q1_notes"]))
        check("mois : la seconde aussi",
              (_bM["q2_tenus"], _bM["q2_notes"]) == (4, 5),
              (_bM["q2_tenus"], _bM["q2_notes"]))
        # La pastille porte sur la quinzaine EN COURS : c est celle qu on solde.
        check("mois : la pastille suit la quinzaine en cours",
              _bM["jours_tenus"] == 4 and _bM["jours_notes"] == 5, _bM["pastille"])
        check("mois : le 10 août, c est la première quinzaine qui compte",
              _obT.bilan_mois("m", "M", "2026-08-10")["jours_notes"] == 10)
        # La barre marque la frontiere : trente et un carres a la file ne
        # disent pas ou s arrete la periode qu on solde.
        _bandeM = _rcT.suite_jours(_bM["suite"], _bM["debut"], _bM["coupure"])
        check("mois : la barre sépare les deux quinzaines",
              "┃" in _bandeM, _bandeM)
        check("mois : elle tombe après le 15e carré",
              _bandeM.index("┃") == 15, _bandeM)
        check("mois : février s arrête au 28",
              _obT.bilan_mois("m", "M", "2026-02-20")["fin"] == "2026-02-28",
              _obT.bilan_mois("m", "M", "2026-02-20")["fin"])
        check("mois : décembre ne déborde pas sur janvier",
              _obT.bilan_mois("m", "M", "2026-12-20")["fin"] == "2026-12-31")
        check("bilan : la légende explique les carrés",
              "🟩" in _pinOb and "🟥" in _pinOb, _pinOb[:220])

        check("bilan : les carrés traduisent la suite",
              _rcT.suite_jours(["tenu", "moyen", "rate", "inconnu"]) == "🟩🟠🟥🟥",
              _rcT.suite_jours(["tenu", "moyen", "rate", "inconnu"]))
        _pinPay = _joinOb(_rcT.bloc_quinzaine(
            [{"e": dict(_eOb, discord="noum0075"), "bilan": _bJ}],
            "2026-08-16", "2026-08-31"))
        check("bilan : le @ Discord est dans le message",
              "@noum0075" in _pinPay, _pinPay)
        check("bilan : les carrés du jour par jour aussi",
              "🟩" in _pinPay and "🟥" in _pinPay, _pinPay)
        # Une fiche sans Discord ne doit pas afficher un « @ » vide.
        check("bilan : pas de @ vide quand le Discord est inconnu",
              "`@`" not in _joinOb(_rcT.bloc_quinzaine(
                  [{"e": dict(_eOb, discord=""), "bilan": _bJ}],
                  "2026-08-16", "2026-08-31")))

        check("report : le message épinglé porte la pastille",
              "🟠" in _pinOb and "VA NOUM 1X1" in _pinOb, _pinOb[:200])
        check("report : et il explique la règle des 80 %",
              "80 %" in _pinOb, _pinOb[:250])
        # La PORTEE se lit dans le nom du salon : « report-compte-jessye » ne
        # suit que jessye. Un suffixe inconnu ne filtre RIEN — un salon nomme
        # un peu de travers deviendrait vide sans que personne comprenne.
        _idsOb = ["jessye", "emma"]
        for _nom, _att in (("report-compte", ""), ("report-comptes", ""),
                           ("report-compte-jessye", "jessye"),
                           ("report-comptes-jessye", "jessye"),
                           ("Report_Compte_Emma", "emma"),
                           ("report-comptes-equipe-1", ""),
                           ("report-compte-fr", ""), ("general", "")):
            check(f"portée : {_nom} -> {_att or 'toutes'}",
                  _rcT.identite_du_salon(_nom, _idsOb) == _att,
                  _rcT.identite_du_salon(_nom, _idsOb))
        # Le bilan peut vivre dans SON salon : « report-quinzaine ». Il ne se
        # lit pas au meme moment que le report du jour — l un le matin pour
        # voir qui decroche, l autre au moment de payer — et laisses ensemble,
        # le bilan descend sous quinze jours de reports.
        check("portée : le salon de quinzaine a son propre préfixe",
              _rcT.PREFIXE_JOUR != _rcT.PREFIXE_QUINZAINE)
        # Les deux familles de noms ne doivent jamais se recouvrir : un salon
        # qui tomberait dans les deux recevrait le report du jour ET le bilan.
        check("portée : aucun nom du jour ne commence comme un nom du mois",
              not any(a.startswith(b) or b.startswith(a)
                      for a in _rcT.PREFIXES_JOUR for b in _rcT.PREFIXES_MOIS),
              (_rcT.PREFIXES_JOUR, _rcT.PREFIXES_MOIS))
        # Les noms que le proprietaire emploie naturellement.
        for _nom in ("report-day", "report-jour", "report-quotidien"):
            check(f"portée : {_nom} est un salon du jour",
                  any(_nom.startswith(x) for x in _rcT.PREFIXES_JOUR))
        for _nom in ("report-mois", "report-du-mois", "report-paie"):
            check(f"portée : {_nom} est un salon du mois",
                  any(_nom.startswith(x) for x in _rcT.PREFIXES_MOIS))
        check("portée : le suffixe d identité marche sur les nouveaux noms",
              _rcT.identite_du_salon("report-day-jessye", _idsOb) == "jessye"
              and _rcT.identite_du_salon("report-mois-emma", _idsOb) == "emma")
        for _nom, _att in (("report-quinzaine", ""),
                           ("report-quinzaine-jessye", "jessye"),
                           ("report-quinzaines-emma", "emma"),
                           ("report-quinzaine-nimporte", "")):
            check(f"portée : {_nom} -> {_att or 'toutes'}",
                  _rcT.identite_du_salon(_nom, _idsOb) == _att,
                  _rcT.identite_du_salon(_nom, _idsOb))

        # Le titre de l epingle dit sur qui il porte, sinon on croit lire tout
        # le monde.
        check("portée : l épingle filtrée nomme son identité",
              "@jessye" in _joinOb(_rcT.bloc_quinzaine(
                  [{"e": _eOb, "bilan": _bOb}],
                  "2026-08-16", "2026-08-31", "jessye")))
        check("portée : l épingle non filtrée ne nomme personne",
              "@jessye" not in _joinOb(_rcT.bloc_quinzaine(
                  [], "2026-08-16", "2026-08-31")).splitlines()[0])

        # Discord refuse au-dela de 2000 caracteres : une liste de 40 fiches
        # doit etre coupee proprement, pas partir en exception a minuit.
        _longOb = _joinOb(_rcT.bloc_quinzaine(
            [{"e": dict(_eOb, va=f"FICHE {_i:02d}"), "bilan": _bOb} for _i in range(60)],
            "2026-08-16", "2026-08-31"))
        check("report : un message trop long est coupé, pas perdu",
              _rcT._taille(_rcT._tronquer(_longOb)) <= 2000
              and "tronquée" in _rcT._tronquer(_longOb),
              _rcT._taille(_rcT._tronquer(_longOb)))
        # LE cas qui a coute la soiree : vingt-deux fiches avec un mois de
        # carres chacune. Toutes doivent arriver, et aucun message ne doit
        # depasser la limite REELLE.
        _bMois = _obT.bilan_mois("m", "M", "2026-08-20")
        _22 = [{"e": dict(_eOb, va=f"FICHE {_i:02d}", discord=f"d{_i}"),
                "bilan": _bMois} for _i in range(22)]
        _msgs22 = _rcT.bloc_quinzaine(_22, _bMois["debut"], _bMois["fin"], "jessye")
        # Le bilan part en EMBED : sa limite est 4096, pas 2000.
        check("mois : aucun message ne dépasse la limite d un embed",
              all(_rcT._taille(m) <= 4096 for m in _msgs22),
              [_rcT._taille(m) for m in _msgs22])
        check("mois : les 22 fiches sont toutes présentes",
              sum(m.count("FICHE ") for m in _msgs22) == 22,
              sum(m.count("FICHE ") for m in _msgs22))
        # « Je veux qu en un morceau il y ait tous les VA. » Un message
        # ordinaire plafonne a 2000 unites, un EMBED a 4096 : c est ce qui
        # permet de tenir vingt-deux fiches et un mois de carres en un seul.
        # On DECOUPE court, volontairement. Un bilan de vingt et une fiches
        # mesurait 2783 unites — sous la limite annoncee de 4096 — et Discord
        # n en affichait pourtant que six. Tant qu on ne sait pas pourquoi,
        # des messages courts passent, et le proprietaire a dit « fais
        # plusieurs trucs s il le faut ». Ce qui compte n est pas d avoir UN
        # message, c est de n en perdre AUCUNE.
        check("mois : chaque morceau reste court",
              all(_rcT._taille(m) <= 1500 for m in _msgs22),
              [_rcT._taille(m) for m in _msgs22])
        check("mois : et toutes les fiches sont là malgré le découpage",
              sum(m.count("FICHE ") for m in _msgs22) == 22,
              sum(m.count("FICHE ") for m in _msgs22))
        # UNE FICHE ABIMEE NE DOIT PAS EMPORTER LE BILAN ENTIER. Un bilan
        # manquant levait KeyError sur 'pastille' ; l exception remontait au
        # try/except de publier et les vingt et une fiches partaient en fumee,
        # pour une seule defaillante, avec une ligne de journal pour trace.
        _casse = [{"e": dict(_eOb, va=f"FICHE {_i:02d}"),
                   "bilan": ({} if _i == 3 else _bMois)} for _i in range(10)]
        _mCasse = _rcT.bloc_quinzaine(_casse, _bMois["debut"], _bMois["fin"], "j")
        check("mois : une fiche sans bilan n emporte pas les autres",
              sum(m.count("FICHE ") for m in _mCasse) == 10,
              sum(m.count("FICHE ") for m in _mCasse))
        # Et si malgre tout une fiche se perdait, le MESSAGE le dit — pas un
        # journal. Ce sont les journaux qui ont laisse passer les trois
        # defauts precedents de la soiree.
        check("mois : aucune alerte quand tout est là",
              not any("manquante" in m for m in _msgs22))

        # L EN-TETE N EST ECRIT QU UNE FOIS. Il pesait quatre cents unites
        # — titre, legende des trois couleurs, regle des 80 %, role de la
        # barre — recopiees sur chaque morceau. Sur une limite dont on sait
        # qu elle est etroite, c est de la place prise aux fiches ; et le
        # proprietaire lit cinq fois la meme legende avant d arriver aux
        # chiffres. « Pas besoin de remettre a chaque fois les phrases. »
        check("mois : la légende n est écrite qu une seule fois",
              sum("carré par jour" in m for m in _msgs22) == 1,
              sum("carré par jour" in m for m in _msgs22))
        check("mois : le titre non plus n est pas répété",
              sum("Bilan du mois" in m for m in _msgs22) == 1)
        # Et ca RAPPORTE : les morceaux suivants tiennent plus de fiches, donc
        # il y en a moins a lire. Vingt et une fiches passaient en six
        # messages, elles en prennent quatre.
        check("mois : en-tête allégé = moins de morceaux",
              len(_msgs22) <= 5, len(_msgs22))
        # Plus de « partie 1/6 » : elle servait a reconnaitre un bilan coupe
        # quand chaque morceau rouvrait sur le meme titre. Un seul le porte
        # desormais, un message sans titre est visiblement une suite.
        check("mois : plus de numérotation de parties",
              not any("partie " in m for m in _msgs22))
        # LE VRAI GARDE-FOU, en remplacement du numero : on recompte les
        # fiches REELLEMENT ecrites et on l annonce DANS le message. Il doit
        # mordre — un garde-fou qui ne se declenche jamais n en est pas un.
        _sauveRe = _rcT._LIGNE_FICHE
        try:
            _rcT._LIGNE_FICHE = __import__("re").compile(
                r"^\S+ \*\*FICHE 0\d\*\*.*\d+/\d+$", __import__("re").M)
            _ampute = _rcT.bloc_quinzaine(_22, _bMois["debut"], _bMois["fin"], "j")
            check("mois : une fiche perdue est ANNONCÉE dans le message",
                  any("manquante" in m for m in _ampute),
                  [m[-90:] for m in _ampute][-1:])
        finally:
            _rcT._LIGNE_FICHE = _sauveRe
        # « QUI MANQUE ? » — la question doit avoir une reponse DANS le
        # message. Une fiche sans aucun compte rattache ne peut pas etre
        # notee, mais la taire rendait la question insoluble : rien ne
        # distinguait un VA inexistant d un VA dont le telephone est vide. Or
        # un telephone vide, sur un document de paie, c est ce qu il faut
        # voir. CLAUDE.md l ecrit noir sur blanc : ne jamais ecarter en
        # silence, compter et remonter.
        _ecT = [("jessye", "Kilishi X1"), ("jessye", "Vou X1")]
        _mEc = _rcT.bloc_quinzaine(_22, _bMois["debut"], _bMois["fin"], "j", _ecT)
        check("mois : les fiches sans compte sont NOMMÉES, pas tues",
              "Kilishi X1" in _mEc[-1] and "Vou X1" in _mEc[-1]
              and "2 fiche(s) sans aucun compte" in _mEc[-1],
              _mEc[-1][-140:])
        # Et elles ne doivent pas passer pour des fiches PERDUES : ce sont
        # deux choses differentes, et confondre les deux ferait crier au bug.
        check("mois : une écartée n est pas comptée comme manquante",
              "manquante" not in _mEc[-1])
        check("mois : sans écartée, aucune ligne parasite",
              "sans aucun compte" not in "".join(_msgs22))
        # LE PIED NE DOIT JAMAIS FAIRE DEBORDER UN MORCEAU. Il etait colle
        # au dernier message APRES le controle de taille : le decoupage
        # tenait son budget de 850, puis on rajoutait quatre cents unites
        # par-dessus, et le dernier morceau repassait a 1080-1284 — au-dela
        # du seuil vers 1100 ou Discord repond « OK » sans afficher la fin.
        # Pire : l alarme etant ecrite en tout dernier, le garde-fou etait la
        # PREMIERE chose mangee. Balayage complet plutot qu un cas choisi.
        _ec27 = [("jessye", f"Fiche vide {_i:02d}") for _i in range(27)]
        _debord, _perdues = [], []
        for _n in range(1, 41):
            _lg = [{"e": dict(_eOb, va=f"F{_i:02d}", discord="d"),
                    "bilan": _bMois} for _i in range(_n)]
            _mm = _rcT.bloc_quinzaine(_lg, _bMois["debut"], _bMois["fin"],
                                      "jessye", _ec27)
            if any(_rcT._taille(_x) > _rcT._MAX_EMBED for _x in _mm):
                _debord.append((_n, [_rcT._taille(_x) for _x in _mm]))
            if sum(_x.count("**F") for _x in _mm) != _n:
                _perdues.append(_n)
        check("mois : le pied ne fait déborder aucun morceau (1 à 40 fiches)",
              not _debord, _debord[:3])
        check("mois : et aucune fiche n est perdue au passage",
              not _perdues, _perdues[:5])
        # L alarme a son PROPRE message, court : une alarme noyee dans un long
        # message est une alarme qu on ne lit pas, et une alarme tronquee
        # n existe pas.
        _pd = _rcT.pied_bilan(_ec27, 21, 17)
        check("mois : l alerte « manquantes » est isolée et courte",
              "manquante" in _pd[-1] and _rcT._taille(_pd[-1]) < 200,
              _rcT._taille(_pd[-1]))
        # UNE IDENTITE DONT TOUS LES TELEPHONES SONT VIDES. La sortie
        # anticipee rendait « Aucune fiche suivie » et s arretait AVANT de
        # nommer les ecartees : tout un monde s effacait d un coup, avec un
        # message indiscernable de « cette identite n a aucun VA ». C est le
        # trou que les ecartees devaient boucher, laisse ouvert dans le cas
        # le plus dangereux — celui ou il n y a rien d autre a afficher.
        _vide = _rcT.bloc_quinzaine([], _bMois["debut"], _bMois["fin"], "jessye",
                                    [("jessye", "Safidy"), ("jessye", "Noum")])
        check("mois : sans aucune fiche notée, les écartées sont quand même nommées",
              "Safidy" in "".join(_vide) and "Noum" in "".join(_vide),
              _vide)
        # Au-dela, on coupe encore, et rien ne se perd.
        _msgs60 = _rcT.bloc_quinzaine(
            [{"e": dict(_eOb, va=f"FICHE {_i:02d}", discord="roucham_79944"),
              "bilan": _bMois} for _i in range(60)],
            _bMois["debut"], _bMois["fin"], "jessye")
        check("mois : soixante fiches, aucune perdue et un seul en-tête",
              sum(m.count("FICHE ") for m in _msgs60) == 60
              and sum("Bilan du mois" in m for m in _msgs60) == 1
              and not any("manquante" in m for m in _msgs60),
              (sum(m.count("FICHE ") for m in _msgs60), len(_msgs60)))
    finally:
        (_obT.OBJECTIFS_FILE, _obT.HISTO_FILE) = _svOb
        shutil.rmtree(_dosOb, ignore_errors=True)
except Exception as _eOb2:
    check("objectifs : testable", False, repr(_eOb2)[:200])

# ==============================================================================
# « Ce qui marche » par identite : les pastilles caption / brut / montage / flash
# ==============================================================================
try:
    import web_upload as _wuST
    _fST = _wuST.STYLES_FILE
    _savST = _fST.read_text(encoding="utf-8") if _fST.exists() else None
    _prevST = _fST.with_suffix(".json.prev")
    _savPrevST = _prevST.read_text(encoding="utf-8") if _prevST.exists() else None
    try:
        _vraiUsersST = _wuST._load_web_users
        _wuST._load_web_users = lambda: {}
        _appST = _wuST.create_app()
        _cST = _appST.test_client()
        with _cST.session_transaction() as _sST:
            _sST["auth"] = True; _sST["username"] = "admin"
            _sST["legacy_owner"] = True; _sST["role"] = "owner"
        _idST = (_wuST._list_identities() or [""])[0]
        check("styles : une identite pour tester", bool(_idST))

        # Les deux tables — celle du serveur et celle servie au navigateur —
        # doivent sortir de la MEME source. Deux listes en dur, c est deux
        # comportements le jour ou l une bouge (le Drive l a deja paye).
        import json as _jsST
        _tableST = _jsST.loads(_wuST._styles_choix_json())
        check("styles : la table servie au navigateur est celle du serveur",
              [x["cle"] for x in _tableST] == list(_wuST._STYLES_CLES)
              and len(_tableST) == 4,
              str([x.get("cle") for x in _tableST])[:80])
        check("styles : chaque style a un emoji et une explication",
              all(x.get("emoji") and x.get("titre") and x.get("label")
                  for x in _tableST) and len(_tableST) > 0)

        # Aller-retour, et ordre NORMALISE : deux identites aux memes styles
        # doivent s afficher pareil, quel que soit l ordre des clics.
        _rST = _cST.post("/identity/styles",
                         data={"identity": _idST, "styles": "flash,caption"}).get_json() or {}
        check("styles : enregistres et relus", _rST.get("ok") is True
              and _wuST.identity_styles(_idST) == ["caption", "flash"],
              str(_rST)[:110])
        check("styles : l ordre ne depend pas de celui des clics",
              _rST.get("styles") == ["caption", "flash"])

        # Le rendu REEL : c est la seule preuve que la pastille arrive a l ecran.
        _hST = _cST.get("/?tab=cloudreels").get_data(as_text=True)
        check("styles : la pastille sort dans la Bibliotheque",
              _hST.count("class='ident-styles'") >= 2,
              f"{_hST.count(chr(39).join([chr(0)]))} ")
        check("styles : elle porte les emoji coches, pas les autres",
              "💬" in _hST and "⚡" in _hST
              and "🎥" not in _hST.split("ident-styles")[1][:400])
        check("styles : le selecteur est dans la modale de modification",
              "ident-edit-styles" in _hST and "identEditStylesPeindre" in _hST)
        check("styles : la modale lit la table servie, pas une copie",
              "ident-styles-choix" in _hST and "identStylesTable" in _hST)

        # Un style invente ne doit rien ecrire NI passer sous silence.
        _rBadST = _cST.post("/identity/styles",
                            data={"identity": _idST, "styles": "flash,zebre"}).get_json() or {}
        check("styles : un style inconnu est refuse, et nomme",
              _rBadST.get("ok") is not True and "zebre" in (_rBadST.get("error") or ""),
              str(_rBadST)[:110])
        check("styles : et le refus n a rien change",
              _wuST.identity_styles(_idST) == ["caption", "flash"])

        # Tout decocher est une ecriture comme une autre — sinon on ne peut
        # jamais retirer la derniere pastille.
        _rVidST = _cST.post("/identity/styles",
                            data={"identity": _idST, "styles": ""}).get_json() or {}
        check("styles : tout decocher marche", _rVidST.get("ok") is True
              and _wuST.identity_styles(_idST) == [], str(_rVidST)[:110])
        check("styles : l identite vide ne laisse pas d entree morte",
              _idST not in (_wuST._load_styles() or {}))
        _hVidST = _cST.get("/?tab=cloudreels").get_data(as_text=True)
        check("styles : plus aucune pastille une fois tout decoche",
              "class='ident-styles'" not in _hVidST)

        # La route previent les menus Discord — mais SEULEMENT quand quelque
        # chose a bouge. Sans ce garde-fou, re-enregistrer la meme fiche
        # relançait une tournee complete sur tout le parc pour rien.
        _majST = []
        _vraiDemST = None
        try:
            import cogs.welcome as _wST
            _vraiDemST = _wST.demander_rafraichissement
            _wST.demander_rafraichissement = (
                lambda bot, raison="", delai=None: (_majST.append(raison), True)[1])
            _wuST._BOT_REF = object()
            _jA = (_cST.post("/identity/styles",
                             data={"identity": _idST, "styles": "montage"}).get_json() or {})
            check("styles : un changement previent les menus Discord",
                  _jA.get("menus_discord") is True and len(_majST) == 1,
                  "%s / %d appel(s)" % (_jA.get("menus_discord"), len(_majST)))
            _jB = (_cST.post("/identity/styles",
                             data={"identity": _idST, "styles": "montage"}).get_json() or {})
            check("styles : re-enregistrer la meme chose ne les reveille pas",
                  _jB.get("ok") is True and _jB.get("menus_discord") is not True
                  and len(_majST) == 1,
                  "%d appel(s) au lieu de 1" % len(_majST))
        finally:
            _wuST._BOT_REF = None
            if _vraiDemST is not None:
                _wST.demander_rafraichissement = _vraiDemST
            _cST.post("/identity/styles", data={"identity": _idST, "styles": ""})

        check("styles : une identite inconnue est refusee",
              (_cST.post("/identity/styles",
                         data={"identity": "zz_nexiste_pas", "styles": "flash"}
                         ).get_json() or {}).get("ok") is not True)
        check("styles : un anonyme ne peut rien poser",
              _appST.test_client().post("/identity/styles",
                                        data={"identity": _idST, "styles": "flash"}
                                        ).status_code == 401)
    finally:
        for _pST, _vST in ((_fST, _savST), (_prevST, _savPrevST)):
            if _vST is not None:
                _pST.write_text(_vST, encoding="utf-8")
            else:
                _pST.unlink(missing_ok=True)
        _wuST._invalidate_json_cache(_fST)
        try:
            _wuST._load_web_users = _vraiUsersST
        except NameError:
            pass
except Exception as _eST:
    check("styles : testable", False, repr(_eST)[:200])

