print("THEMES : le serveur et le navigateur connaissent les MEMES")
print("=" * 70)
try:
    import re as _reTh2, pathlib as _plTh2
    _srcTh2 = _plTh2.Path("web_upload.py").read_text(encoding="utf-8")
    # La table des LIBELLES est la liste de reference : c'est elle qui dit
    # quels themes existent, et elle sert au selecteur.
    _mTh2 = _reTh2.search(r"return \(\{dark:'sombre'(.*?)\}\)\[t\]", _srcTh2, _reTh2.S)
    _tous = set(_reTh2.findall(r"(\w+):'", _mTh2.group(0))) if _mTh2 else set()
    # Cinq depuis que trois ont ete mis de cote. Le seuil dit « au moins
    # quatre » : il verifie que la table est LISIBLE, pas combien elle
    # contient -- sinon chaque ajout ou retrait casse un test qui n'a rien
    # a voir.
    check("themes : la table des libelles est lisible",
          len(_tous) >= 4, str(sorted(_tous)))

    # LE SERVEUR PEINT LA PAGE AVANT QUE LE JAVASCRIPT TOURNE. Un theme qu'il
    # ne reconnait pas retombe sur « light » : le navigateur affiche une page
    # BLANCHE, cartes comprises, puis le script la repeint. C'est exactement
    # ce qui est arrive a « infloww » -- declare partout cote client, oublie
    # dans ces trois tables-la.
    _d = _srcTh2.index("# defaut du site")
    _bloc = _srcTh2[_d - 500:_d + 900]
    _manquants = sorted(t for t in _tous if ("\"%s\"" % t) not in _bloc)
    check("themes : le serveur accepte tous les themes du selecteur",
          not _manquants,
          "absent(s) de la liste, du _pre ou du _bod : " + ", ".join(_manquants))

    # Et cote client, les memes doivent figurer dans le nettoyage des classes,
    # sinon deux themes se superposent au changement.
    _mCl = _reTh2.search(r"b\.classList\.remove\(([^)]*)\)", _srcTh2)
    _nett = set(_reTh2.findall(r"'(\w+)'", _mCl.group(1))) if _mCl else set()
    _oubl = sorted(t for t in _tous if t != "dark" and t not in _nett)
    check("themes : changer de theme nettoie toutes les classes",
          not _oubl, "pas nettoye(s) : " + ", ".join(_oubl))

    # La pre-peinture des variantes sombres a besoin de sa palette.
    _mPal = _reTh2.search(r"var PAL = \{(.*?)\}\[theme\]", _srcTh2, _reTh2.S)
    _pal = set(_reTh2.findall(r"(\w+):\[", _mPal.group(1))) if _mPal else set()
    _mVar = _reTh2.search(r"VABOT_DARK_VARIANTS = \[([^\]]*)\]", _srcTh2)
    _vars = set(_reTh2.findall(r"'(\w+)'", _mVar.group(1))) if _mVar else set()
    check("themes : chaque variante sombre a sa palette de pre-peinture",
          _vars and _vars <= _pal,
          "sans palette : " + ", ".join(sorted(_vars - _pal)))

    # Et la preuve par le rendu : le cookie doit gouverner la classe du body.
    import web_upload as _wTh3
    _aTh3 = _wTh3.create_app(); _aTh3.testing = True
    _svTh3 = _wTh3._load_web_users
    _wTh3._load_web_users = lambda: {"boss": {"role": "owner", "password": "x"}}
    try:
        _cTh3 = _aTh3.test_client()
        with _cTh3.session_transaction() as _sTh3:
            _sTh3["auth"] = True; _sTh3["username"] = "boss"; _sTh3["role"] = "owner"
        _faux = []
        for _t in sorted(_tous):
            _cTh3.set_cookie("va_theme", _t)
            _h3 = _cTh3.get("/").get_data(as_text=True)
            _mb = _reTh2.search(r"<body[^>]*class=\"([^\"]*)\"", _h3)
            _cls = (_mb.group(1) if _mb else "")
            if _t == "dark":
                if _cls.strip():
                    _faux.append("%s -> %s" % (_t, _cls))
            elif _t not in _cls.split():
                _faux.append("%s -> %s" % (_t, _cls or "(rien)"))
        check("themes : le cookie gouverne la classe du body, des le serveur",
              not _faux, " | ".join(_faux[:4]))
        # MIS DE COTE, PAS EFFACES. Le proprietaire a retire trois themes du
        # selecteur (« des themes a chier ») en demandant de les garder « sans
        # les afficher ». Leur feuille de style reste donc dans le fichier :
        # les remettre est une ligne, pas une reecriture.
        _RETIRES = ("obsidian", "violet", "gold")
        check("themes : les trois retires ne sont plus proposes",
              not any(("setTheme('%s')" % t) in _srcTh2 for t in _RETIRES),
              "encore dans le selecteur")
        check("themes : mais leur feuille de style est GARDEE de cote",
              all(("body.%s{" % t) in _srcTh2 for t in _RETIRES),
              "effacee — les remettre demanderait de tout reecrire")
        # Et celui qui en avait un ne doit pas se prendre un ecran blanc.
        _blancs = []
        for _t in _RETIRES:
            _cTh3.set_cookie("va_theme", _t)
            _hh = _cTh3.get("/").get_data(as_text=True)
            _mb2 = _reTh2.search(r"<body[^>]*class=\"([^\"]*)\"", _hh)
            if "light" in (_mb2.group(1) if _mb2 else ""):
                _blancs.append(_t)
        check("themes : un theme retire retombe sur SOMBRE, jamais sur clair",
              not _blancs, "renvoyes au blanc : " + ", ".join(_blancs))
        check("themes : le gris secondaire d Infloww est celui releve",
              "color:#999999!important" in _srcTh2)

        # INFLOWW LIGHT : meme exigence que son jumeau sombre, un theme
        # declare a moitie se choisit sans s appliquer.
        for _ou, _quoi in (
                ("body.light.inflowwlight{", "sa regle de fond"),
                ("'pre-infloww','pre-inflowwlight'", "le nettoyage du html"),
                ("theme === 'inflowwlight'", "sa pre-peinture"),
                ("inflowwlight:'Infloww light'", "son nom affiche"),
                ('data-theme="inflowwlight"', "sa carte dans les reglages")):
            check("infloww light : %s est declaree" % _quoi, _ou in _srcTh2)
        # Un theme CLAIR doit poser body.light : c est le socle. Sans lui,
        # les textes restent ceux du theme sombre et s effacent sur le blanc.
        check("infloww light : il se monte SUR le theme clair",
              "b.classList.add('light'); b.classList.add('inflowwlight');" in _srcTh2)
        # Ses couleurs a lui : le bleu rempli de sa capture dans la vignette,
        # et le gris neutre plutot que le #6b7280 bleute du theme clair.
        check("infloww light : l encre pale est le gris neutre d Infloww",
              "color:#666666!important" in _srcTh2)

        # SOMBRE et CLAIR ont quitte le SELECTEUR. Leur feuille de style, elle,
        # ne peut pas partir : body.light est le socle d Apple, de Claude et
        # d Infloww light, et « dark » est l absence de classe.
        check("themes : sombre et clair ne sont plus proposes",
              not any(("setTheme('%s')" % t) in _srcTh2 for t in ("dark", "light")),
              "encore dans le selecteur")
        check("themes : mais le socle clair est toujours la",
              "body.light{" in _srcTh2)

        # LES LISTES DE THEMES ECRITES A LA MAIN, LOIN DU BLOC DES THEMES.
        # On ne les trouve pas en cherchant le nom de son theme : elles
        # nomment les AUTRES. La plus importante remet le bouton Supprimer en
        # ROUGE, theme par theme -- parce que chaque theme repeint tous les
        # boutons en !important avec sa couleur d accent. Un theme oublie
        # ici donne un bouton destructeur BLEU, indiscernable du bouton
        # d action principale. Les deux Infloww y manquaient tous les deux.
        _dbl = _srcTh2[_srcTh2.index("body.obsidian button.danger-btn"):]
        _dbl = _dbl[:_dbl.index("}") + 1]
        _bleus = sorted(t for t in _tous if t not in ("dark", "light")
                        and ("." + t + " button.danger-btn") not in _dbl)
        check("themes : le bouton Supprimer reste ROUGE dans chaque theme",
              not _bleus, "il prend l accent (donc bleu) dans : " + ", ".join(_bleus))
        check("themes : quatre cartes dans le selecteur, pas une de plus",
              _srcTh2.count('onclick="setTheme(') == 4,
              "%d carte(s)" % _srcTh2.count('onclick="setTheme('))

        # PAS DE PASTILLE AU CHANGEMENT DE THEME. Elle annoncait « Theme X
        # active » par-dessus une page qui venait entierement de changer de
        # couleur : elle n apprenait rien et recouvrait un coin de l ecran.
        _sT = _srcTh2[_srcTh2.index("function setTheme(theme){"):
                      _srcTh2.index("// PAS DE NOTIFICATION ICI")]
        check("themes : changer de theme n affiche plus de notification",
              "showToast" not in _sT, "la pastille est revenue")

        # LE DEFAUT DOIT ETRE LE MEME MOT DES DEUX COTES. Le serveur ecrit la
        # classe du body avant que le JavaScript tourne ; si les deux defauts
        # different, la page part dans une apparence puis se fait repeindre
        # dans l autre. C est exactement l ecran blanc au rechargement.
        _dSrv = _srcTh2.split("# defaut du site")[0].rsplit('_th = "', 1)[-1].split('"')[0]
        _mot = "localStorage.getItem('vabot_theme') || '"
        # Le repli VIDE ne compte pas : un troisieme lecteur du theme ne
        # cherche pas le defaut, il demande seulement « est-ce Apple ? »
        # pour poser les icones iOS.
        _dCli = set(p.split("'")[0] for p in _srcTh2.split(_mot)[1:]) - {""}
        check("themes : le serveur et le navigateur ont le MEME defaut",
              _dCli == {_dSrv},
              "serveur %s, navigateur %s" % (_dSrv, sorted(_dCli)))
        check("themes : les deux scripts du navigateur declarent ce defaut",
              _srcTh2.count(_mot + _dSrv) == 2,
              "%d script(s) au lieu de 2" % _srcTh2.count(_mot + _dSrv))
        check("themes : et ce defaut se trouve dans le selecteur",
              ("setTheme('%s')" % _dSrv) in _srcTh2,
              "defaut %s : personne ne peut le rechoisir" % _dSrv)
    finally:
        _wTh3._load_web_users = _svTh3
except Exception as _eTh2:
    check("themes : coherence testable", False, repr(_eTh2)[:200])

