        _mF2 = _eqE.ajouter_membre("Noum bis", role="Monteur", discord="@noum_alt", chemin=_pF)
        _rF = _eqE.fusionner(_mF1["id"], _mF2["id"], chemin=_pF)
        _gF2 = _eqE.lire(chemin=_pF)["membres"][0]
